// CCAR-P Revision — Domain 6: Stakeholder Communication & Lifecycle (14%) — 43 items
window.QUESTIONS = (window.QUESTIONS || []).concat([
{ id:"d6-01", domain:6, type:"single", select:1, difficulty:"core", source:"generated",
  question:"An executive sponsor asks whether to use a larger model or a lower-cost model. Which response best supports an informed decision?",
  options:["Recommend the larger model because its pilot score is higher, then review serving cost after launch","Recommend the smaller model to protect budget, with complex-case misses handled by operations","Compare measured quality, total cost, principal risk, and migration effort against the sponsor's target","Run both models for the first year and postpone selecting a primary route until renewal"],
  correct:[2],
  explanation:"The sponsor needs evidence tied to the agreed target, the business risk of each choice, and the cost of changing direction later. The other responses optimize one consideration or defer the decision without making the tradeoff explicit." },
{ id:"d6-02", domain:6, type:"single", select:1, difficulty:"core", source:"generated",
  question:"In the first discovery workshop with a non-technical claims team, which opening question is most useful?",
  options:["Which model tier should procurement reserve for the project?","Walk me through today's claim process and what a successful improvement would change","Which accuracy level should appear in the delivery contract before discovery ends, while leverage is highest?","Which current tool should be replaced first to create visible momentum?"],
  correct:[1],
  explanation:"Current process, pain points, and desired outcomes provide the evidence needed to form requirements. The other questions prematurely select technology, negotiate a commitment, or assume replacement is the goal." },
{ id:"d6-03", domain:6, type:"single", select:1, difficulty:"core", source:"generated",
  question:"During discovery, a sponsor says the data is clean, staff will adopt the assistant, and legal has no objections. None of these claims is verified. What should the architect do?",
  options:["Record each claim as an assumption with an owner, validation method, and decision date","Treat the claims as provisional requirements because the executive sponsor supplied them","Pause architecture work until data, adoption, and legal reviews are complete","Record the data claim because adoption and legal review sit outside architecture"],
  correct:[0],
  explanation:"Unverified claims should remain visible and testable rather than silently becoming design facts. Ownership and validation dates let work proceed while exposing decisions that may change scope." },
{ id:"d6-04", domain:6, type:"multi", select:2, difficulty:"core", source:"generated",
  question:"Which TWO outputs should structured discovery produce before architecture design begins?",
  options:["A prioritized implementation backlog with estimates and acceptance tests","Requirements linked to business outcomes and accountable decision owners","An approved production prompt, guardrail package, and release plan","A support model with incident staffing and escalation assignments","Assumptions and constraints with validation owners and target dates"],
  correct:[1,4],
  explanation:"Design should begin from traceable requirements and a visible set of assumptions and constraints. Backlogs, production prompts, and support staffing depend on decisions made after discovery." },
{ id:"d6-05", domain:6, type:"single", select:1, difficulty:"core", source:"generated",
  question:"A sponsor sees a strong pilot demo and assumes the production assistant will not make mistakes. When and how should the architect address that expectation?",
  options:["At pilot exit, report the aggregate pass rate and place remaining limitations in an appendix","At contract review, set a quality target and defer failure examples until acceptance testing","From the first demo, pair representative successes with measured failures and their handling path","After the first production incident, reset expectations using observed impact and remediation"],
  correct:[2],
  explanation:"Expectation alignment starts before stakeholders generalize from a successful demonstration. Showing measured limitations and the handling path makes residual risk part of the design discussion rather than a post-launch surprise." },
{ id:"d6-06", domain:6, type:"single", select:1, difficulty:"core", source:"generated",
  question:"Which commitment is the best-formed SLA for an AI assistant?",
  options:["For the agreed workload, median latency stays below three seconds and user satisfaction is reviewed monthly","For the agreed workload, p95 latency is below three seconds, test-set accuracy is at least 95%, and breach remediation is defined","For the agreed workload, accuracy is 99% on a vendor benchmark and breach terms are negotiated after an incident","For the agreed workload, p95 latency is below three seconds while accuracy trends are reviewed each quarter"],
  correct:[1],
  explanation:"A usable SLA defines the workload, measurement, threshold, and breach response. The alternatives use an unsuitable statistic or benchmark, omit breach handling, or leave part of the commitment undefined." },
{ id:"d6-07", domain:6, type:"single", select:1, difficulty:"hard", source:"generated",
  question:"The same routing decision must be presented to the CISO and the CFO. What should change between the two conversations?",
  options:["Use the same evidence and emphasis so both stakeholders receive a consistent recommendation","Adjust the recommendation to match each executive's preferred outcome while retaining the evidence","Keep the facts constant; frame controls for the CISO and financial exposure for the CFO","Give the CFO a shorter cut of the CISO material; its framing left unchanged"],
  correct:[2],
  explanation:"Audience adaptation changes emphasis, not facts. The CISO and CFO evaluate the same decision through different responsibilities, so the presentation should connect common evidence to each stakeholder's decision criteria." },
{ id:"d6-08", domain:6, type:"single", select:1, difficulty:"core", source:"generated",
  question:"Eighteen months after launch, a successor asks why the system uses retrieval rather than fine-tuning. Which artifact best preserves the answer?",
  options:["A decision record covering context, alternatives, rationale, consequences, and review conditions","A current architecture diagram annotated with component owners and data flows","Repository history and issue links from the original implementation period","An operations runbook describing current behavior and common recovery steps"],
  correct:[0],
  explanation:"A decision record preserves why an option was chosen and what would justify revisiting it. Diagrams, repository history, and runbooks describe implementation or operation but do not reliably preserve the original tradeoff." },
{ id:"d6-09", domain:6, type:"single", select:1, difficulty:"core", source:"generated",
  question:"Which handoff package most completely enables a client's operations team to run and safely change the system?",
  options:["Runbooks, source access, deployment manifests, and current diagrams, but no decision history or control evidence","Decision records, architecture diagrams, and the control register, but no operating procedures or escalation guidance","Monitoring guidance, support contacts, and a training recording, with unresolved design questions left to the delivery team","Runbooks and configuration references plus decision rationale, rejected alternatives, control owners, escalation paths, and evidence locations"],
  correct:[3],
  explanation:"A complete handoff supports daily operation, incident response, and safe future change. It combines operational guidance with the rationale, ownership, and evidence behind load-bearing decisions." },
{ id:"d6-10", domain:6, type:"single", select:1, difficulty:"core", source:"generated",
  question:"A steering committee receives the same detailed architecture document as the engineering team and finds it unusable. Which documentation approach should replace it?",
  options:["Replace the engineering document with a shorter executive version used across audiences, so every reader shares one source of truth","Provide audience-specific layers or views while retaining a detailed engineering record","Keep the technical document unchanged and add a glossary for non-technical readers","Send the committee the final recommendation and omit its supporting rationale"],
  correct:[1],
  explanation:"Different audiences use architecture documentation to make different decisions. Tailored layers or views preserve engineering depth while giving sponsors and operators the information they need." },
{ id:"d6-11", domain:6, type:"multi", select:2, difficulty:"core", source:"generated",
  question:"Which TWO changes should trigger an unscheduled architecture review?",
  options:["A new regulation changes the workload's retention obligations","A quarterly value review reaches its planned calendar date","A new engineer requests the team's preferred framework","The support team reorganizes its on-call rotation without changing system constraints","The model version used in production receives a retirement notice"],
  correct:[0,4],
  explanation:"A changed regulatory obligation and a model retirement notice can invalidate architecture assumptions and require an unscheduled review. Calendar reviews remain valid scheduled governance events, while staffing preferences or routine support changes do not independently change the architecture." },
{ id:"d6-12", domain:6, type:"single", select:1, difficulty:"core", source:"generated",
  question:"Accuracy remains below the contractual floor for a week. Which response best follows a defined SLA breach process?",
  options:["Notify stakeholders, assign remediation with a deadline, restore the service objective, and complete a post-incident review","Open an incident and remediate internally, notifying stakeholders if the next reporting period also fails","Pause traffic and negotiate a temporary waiver before beginning root-cause analysis","Notify stakeholders and restore performance, but defer the incident review to the next quarterly meeting"],
  correct:[0],
  explanation:"A complete breach response combines timely communication, owned remediation, restoration, and learning. The alternatives delay required communication, reorder the response around negotiation, or omit timely review." },
{ id:"d6-13", domain:6, type:"single", select:1, difficulty:"hard", source:"generated",
  question:"A document workflow designed for 1,000 files per day now handles 40,000 files and four languages, while repeated component patches fail. What is the best next step?",
  options:["Tune the classifier and add capacity because each change can still be measured independently","Revisit the architecture because scale and language requirements invalidate foundational assumptions","Add queue buffering and retain the design until utilization data proves a hard platform limit","Split traffic by language within the current pattern and reassess after the next reporting period, limiting change risk"],
  correct:[1],
  explanation:"Repeated local fixes are poor leverage when the original volume and scope assumptions no longer hold. The architecture should be reconsidered against the new workload rather than patched around invalid premises." },
{ id:"d6-14", domain:6, type:"single", select:1, difficulty:"core", source:"generated",
  question:"Monitoring shows that a deployed claims assistant meets its service targets, but users abandon one optional review step because its confirmation text is unclear. What should the architect recommend next?",
  options:["Set a step-level adoption criterion, test revised confirmation text, and review the result","Open an architecture review because the business outcome has not yet improved","Release revised text and use overall satisfaction to assess the change","Add user training and revisit the step at the next value review"],
  correct:[0],
  explanation:"The service targets still hold, and the evidence isolates a usability problem. A bounded change with a step-level measure tests the identified cause; overall satisfaction, training alone, or a full architecture review would not." },
{ id:"d6-15", domain:6, type:"single", select:1, difficulty:"core", source:"generated",
  question:"Where should governance checkpoints sit in the operating lifecycle?",
  options:["Use one approval before launch and let observability govern later changes","Place recurring risk and value reviews inside the operating loop, with owners and follow-up actions","Schedule an annual legal review and keep it separate from product iteration","Start governance review after an incident threshold is crossed, using the incident process as the trigger"],
  correct:[1],
  explanation:"Governance is an operating practice, not a one-time approval or incident-only response. Recurring checkpoints connect evidence to accountable decisions and follow-up work." },
{ id:"d6-16", domain:6, type:"single", select:1, difficulty:"core", source:"generated",
  question:"For a regulated enterprise claims assistant, which initial stakeholder map is the strongest starting point before discovery expands it?",
  options:["Executive sponsor, claims process owner, finance, and vendor management","Kickoff attendees, delivery lead, procurement, and data engineering","Executive sponsor, claims users, operations, security, and legal or compliance","Product owner, implementation engineers, support desk, and procurement"],
  correct:[2],
  explanation:"The starting map should cover value, workflow reality, operability, security, and regulatory obligations. It can expand as discovery identifies additional decision owners and affected groups." },
{ id:"d6-17", domain:6, type:"single", select:1, difficulty:"core", source:"generated",
  question:"Mid-project, a sponsor requests voice input, two additional languages, and a mobile interface. What is the most disciplined response?",
  options:["Accept the additions against contingency budget and revisit the schedule after implementation begins","Defer the additions to the next contract period to preserve the original baseline","Prototype the additions before estimating their effect so the sponsor can see early progress","Assess effects on outcomes, controls, cost, and schedule, then let the sponsor choose with those tradeoffs visible"],
  correct:[3],
  explanation:"Scope can change, but the decision should use the recorded baseline and a visible impact assessment. This preserves sponsor ownership without hiding cost, risk, or schedule consequences." },
{ id:"d6-18", domain:6, type:"single", select:1, difficulty:"core", source:"generated",
  question:"Two departments describe the same approval process differently during discovery. What should the architect do before converting either account into requirements?",
  options:["Map both current-state variants, identify the decision owner, and validate when each version applies","Use the executive sponsor's description as the standard process and record the other as an exception, since sponsor authority resolves conflicts fastest","Design for the more complex description and treat the simpler version as a supported subset","Average the timing and volume claims from both groups, then refine them during the pilot"],
  correct:[0],
  explanation:"Conflicting accounts are discovery evidence, not a reason to choose a favorite version. The architect should expose the variants, establish who can resolve the conflict, and validate the conditions before writing requirements." },
{ id:"d6-19", domain:6, type:"single", select:1, difficulty:"hard", source:"generated",
  question:"Policy permits either a global or single-region route. The CISO favors isolation, while the CFO favors the lower-cost option. Which presentation best supports a decision?",
  options:["Recommend the global route because policy permits it and recurring cost affects the full workload","Recommend the regional route because security preference should resolve a close decision","Present measured cost, residual risk, control differences, and migration effort","Run a longer latency benchmark, the business decision postponed, one route winning technically"],
  correct:[2],
  explanation:"When policy permits both choices, the architect should make the competing business consequences explicit and identify the decision owner. A technical benchmark or unilateral preference does not resolve financial, control, and reversal tradeoffs." },
{ id:"d6-20", domain:6, type:"single", select:1, difficulty:"core", source:"generated",
  question:"After deployment, an advisory assistant becomes a required step before claims can be released, increasing business criticality. What should happen to its SLA?",
  options:["Keep the existing SLA so pre-change and post-change performance remain directly comparable","Reassess thresholds, measurement, ownership, and breach actions with the sponsor and operations team","Reduce the quality threshold until the newly critical workflow produces few reported breaches","Add more dashboard panels while leaving the original service commitments unchanged"],
  correct:[1],
  explanation:"A material change in business criticality changes the consequence of failure. Stakeholders should revisit the thresholds, how they are measured, who responds, and what a breach requires." },
{ id:"d6-21", domain:6, type:"single", select:1, difficulty:"core", source:"generated",
  question:"Before the architect leaves, operators can restart the service but cannot tell which changes require architectural escalation. What handoff addition closes that gap?",
  options:["Add more detailed restart steps and screenshots to the existing operations runbook","Expand the architecture diagram to show components and data connections","Document load-bearing assumptions, safe-change boundaries, escalation criteria, and accountable owners","Schedule recurring office hours so operators can ask the departing architect about proposed changes, preserving access to the reasoning"],
  correct:[2],
  explanation:"Operators need decision boundaries, not only recovery instructions or diagrams. Explicit assumptions, escalation criteria, and ownership let the team distinguish routine change from architecture change without permanent dependence." },
{ id:"d6-22", domain:6, type:"multi", select:3, difficulty:"core", source:"generated",
  question:"Which THREE conditions show that a deployment is ready to move from handoff into routine monitoring?",
  options:["Named operating owners and escalation paths have been exercised","The current feature backlog has been prioritized and estimated","Monitoring and feedback triggers are configured with a review cadence","The delivery architect remains the primary incident contact for the first quarter","Operators have used the runbooks and decision records in a handoff exercise"],
  correct:[0,2,4],
  explanation:"The transition is ready when ownership and escalation work in practice, monitoring triggers are active, and operators can use the handoff material. A prioritized feature backlog or continued dependence on the delivery architect is not a readiness condition." },
{ id:"d6-23", domain:6, type:"single", select:1, difficulty:"core", source:"generated",
  question:"A client is standardized on AWS, uses AWS identity and security controls, and has committed cloud spend. Which route recommendation best connects those constraints to the architecture?",
  options:["Use the direct Claude API for broader feature access and integrate the AWS controls separately","Use Amazon Bedrock to align authentication, billing, security boundaries, and committed AWS spend","Use a third-party SaaS platform to reduce dependence on the client's existing cloud environment, preserving negotiating leverage","Choose the route with the lowest token price and add governance controls after procurement"],
  correct:[1],
  explanation:"The client's existing governance, identity, billing, and procurement commitments favor Amazon Bedrock. Feature breadth and price still matter, but they should be evaluated after mandatory operating constraints." },
{ id:"d6-24", domain:6, type:"single", select:1, difficulty:"core", source:"generated",
  question:"A product team prioritizes broad access to current Claude features and direct Anthropic billing and support. Which route best fits?",
  options:["Amazon Bedrock, using AWS identity and billing while accepting platform feature differences","Google Cloud Agent Platform, using Google Cloud identity and consolidated billing","The direct Claude API, providing direct model access and Anthropic billing and support","A third-party platform, standardizing procurement even when feature timing differs"],
  correct:[2],
  explanation:"The direct Claude API best matches a requirement for direct Anthropic access, billing, support, and broad feature availability. Cloud platforms are stronger when their native governance or consolidated billing is the deciding constraint." },
{ id:"d6-25", domain:6, type:"single", select:1, difficulty:"core", source:"generated",
  question:"An approved architecture requires model inference to remain in one named region. What implementation guidance should the architect hand to engineering and compliance?",
  options:["A diagram naming the cloud platform, with endpoint details left to the implementation team","A requirement-to-control row naming the approved route and region, exact configuration point, verification procedure, evidence artifact, and owner","A provider compliance brochure attached to the design, with the team asked to retain screenshots if questions arise","A note that regional execution is mandatory, with final validation deferred to the first production audit"],
  correct:[1],
  explanation:"Implementation guidance must make the approved decision executable and auditable: identify the route and region, where the setting is enforced, how it is verified, what evidence proves it, and who owns the control. A diagram, brochure, or deferred audit records intent without giving engineering and compliance a complete operating instruction." },
{ id:"d6-26", domain:6, type:"single", select:1, difficulty:"hard", source:"generated",
  question:"A client requests an abstraction layer so the system can switch model providers quickly. What is the most defensible architectural counsel?",
  options:["Abstract provider APIs now and limit the design to shared features before defining a switch event","Estimate realistic switch scenarios, then fund portability in proportion to their probability and business impact","Use provider-specific features and document a manual migration without estimating the required recovery time","Maintain live dual-provider capacity for the full workload to demonstrate switching readiness"],
  correct:[1],
  explanation:"Portability is an investment that should be sized against a credible switch scenario and its consequences. The alternatives commit to too much or too little portability before defining the business need." },
{ id:"d6-27", domain:6, type:"single", select:1, difficulty:"core", source:"generated",
  question:"Procurement asks for a delivery-route comparison based on price. How should the architect structure the decision instead?",
  options:["Rank routes by effective unit price, then list compliance exceptions beside the ranking","Run separate technical and commercial reviews so neither set of criteria constrains the other","Shortlist routes by feature breadth, then let procurement evaluate controls and contractual terms, since commercial review is procurement's mandate","Use governance and compliance as gates, then compare latency, feature fit, support, and total cost"],
  correct:[3],
  explanation:"A route that cannot satisfy mandatory governance or compliance conditions should not win on price. The remaining viable routes can then be compared across operational and commercial factors." },
{ id:"d6-28", domain:6, type:"single", select:1, difficulty:"core", source:"generated",
  question:"Which sequence best orders the architect's stakeholder and operating lifecycle?",
  options:["Discovery → design → handoff → monitoring → iteration","Discovery → design → monitoring → handoff → iteration","Discovery → handoff → design → monitoring → iteration","Design → discovery → handoff → iteration → monitoring"],
  correct:[0],
  explanation:"Discovery establishes outcomes and constraints, design turns them into decisions, handoff transfers operation and rationale, monitoring supplies evidence, and iteration changes the system from that evidence." },
{ id:"d6-29", domain:6, type:"single", select:1, difficulty:"core", source:"generated",
  question:"Three months after handoff, the client still routes every routine incident to the delivery architect. What does this most strongly indicate?",
  options:["The escalation policy is working because incidents reach the person with the most design context","The operations team needs broader permissions, but the handoff itself is otherwise complete","The handoff missed its autonomy goal and needs remediation in runbooks, training, or escalation design","The service should transfer permanently back to the delivery team under a higher support tier"],
  correct:[2],
  explanation:"Routine operation should not depend on the original architect. Continued dependence indicates that operating guidance, training, permissions, or escalation boundaries are incomplete." },
{ id:"d6-30", domain:6, type:"single", select:1, difficulty:"hard", source:"generated",
  question:"A sponsor asks whether the assistant will reach 99% accuracy by Q3, but available evidence does not support that commitment. How should the architect respond?",
  options:["Commit provisionally to 99% and revisit the promise after the next evaluation cycle","Decline to discuss a future target until a complete production dataset is available","Report the evidence and agreed target, 99% stated as not committed, residual handling explained","Use the best pilot score as the Q3 forecast, a confidence range attached, caveats noted"],
  correct:[2],
  explanation:"The response should distinguish measured performance, an agreed target, and an unsupported aspiration. It should also explain how residual errors are handled without inventing results or promising a date the evidence cannot support." },
{ id:"d6-31", domain:6, type:"multi", select:3, difficulty:"core", source:"generated",
  question:"Which THREE practices make a steering-committee architecture discussion decision-ready?",
  options:["Present the recommended option without alternatives so the meeting stays focused","State the decision required and identify the accountable decision-maker","Tie the evidence to the agreed business outcome and constraints","Place implementation detail for each component on the main decision slide","Name unresolved assumptions that could change the recommendation"],
  correct:[1,2,4],
  explanation:"A decision-ready discussion makes the decision and owner explicit, connects evidence to agreed outcomes and constraints, and exposes assumptions that could alter the recommendation. Suppressing alternatives or overloading the main slide weakens the decision." },
{ id:"d6-32", domain:6, type:"single", select:1, difficulty:"core", source:"generated",
  question:"An engineer proposes a multi-agent redesign but cannot identify a requirement or acceptance criterion it serves. What should the architect do?",
  options:["Prototype it behind a feature flag and seek a requirement if the metrics improve","Pause the proposal until it is linked to a confirmed requirement and measurable acceptance criterion","Classify it as platform modernization owned by engineering rather than the business","Add it as a research spike with no production acceptance criterion"],
  correct:[1],
  explanation:"Architecture work should trace to a confirmed need and a way to judge success. A prototype or research label does not justify redesigning a production system without a requirement." },
{ id:"d6-33", domain:6, type:"single", select:1, difficulty:"core", source:"generated",
  question:"An assistant meets its agreed aggregate quality floor, but 4% of cases remain high risk. What should the sponsor-facing operating plan include?",
  options:["Raise the aggregate target until the residual category disappears from routine reporting, so the metric reflects only actionable cases","Treat the passing aggregate score as sufficient and monitor the overall average","Define human review for the residual cases and track their volume and outcomes separately","Exclude the high-risk cases from the SLA and route them through incident management"],
  correct:[2],
  explanation:"Meeting an aggregate floor does not remove the need to control consequential residual cases. The operating plan should name their handling path and measure whether that path remains effective." },
{ id:"d6-34", domain:6, type:"single", select:1, difficulty:"core", source:"generated",
  question:"Feedback intake, weekly triage, and a backlog exist, but the same complaints recur because no one decides when a signal requires action. What is missing?",
  options:["A larger survey sample collected before each weekly triage session","A named decision owner with a trigger, action, and review criteria","Additional feedback channels for users who do not attend review meetings","A quarterly feature roadmap maintained separately from the feedback process"],
  correct:[1],
  explanation:"Collection and triage do not form a complete feedback loop without accountable decision-making. Each meaningful signal needs a trigger, owner, action, and a check that the action resolved the problem." },
{ id:"d6-35", domain:6, type:"single", select:1, difficulty:"core", source:"generated",
  question:"What is the purpose of a recurring value review with the sponsor after deployment?",
  options:["Verify SLA compliance and close the meeting when operational thresholds are met","Recheck whether performance still produces the intended outcome","Review upcoming features and collect sponsor preferences for the next release","Refresh scope and budget before examining evidence about business outcomes"],
  correct:[1],
  explanation:"A value review reconnects operating evidence to the business outcome and supports a lifecycle decision. SLA compliance and roadmap discussion can inform the meeting but do not replace that decision." },
{ id:"d6-36", domain:6, type:"single", select:1, difficulty:"core", source:"generated",
  question:"A sponsor's only stated requirement is that the assistant must feel seamless. What is the best discovery move?",
  options:["Probe what users must not notice, what can fail, and how success can be tested","Record seamless as a provisional requirement and define its metric after design","Choose a low-latency architecture and validate the preference during the pilot","Treat the statement as a user-experience concern owned outside architecture"],
  correct:[0],
  explanation:"A preference becomes useful only after discovery translates it into bounded, testable conditions. Selecting an architecture first or deferring the definition leaves the design anchored to an ambiguous word." },
{ id:"d6-37", domain:6, type:"single", select:1, difficulty:"core", source:"generated",
  question:"A compliance lead says policy requires 30-day retention but cannot yet provide the policy. How should discovery record the statement?",
  options:["Record it as a confirmed requirement because the compliance lead supplied it","Record it as an assumption without linking it to the claimed policy source","Record it as pending, linked to the claimed policy, with an owner and pre-design validation date","Exclude it from discovery until the written policy is available, then reopen the requirements process"],
  correct:[2],
  explanation:"Requirements may come from authoritative policies, contracts, regulations, or stakeholder evidence, but unverified source claims should not be treated as confirmed. Recording the claimed source, owner, and validation deadline preserves traceability without hiding uncertainty." },
{ id:"d6-38", domain:6, type:"single", select:1, difficulty:"core", source:"generated",
  question:"A team is comparing direct integration with a provider-neutral abstraction layer. Which estimate belongs specifically under reversal cost?",
  options:["The monthly serving cost at the forecast production volume","The probability that each option meets the current latency target","The engineering, retesting, migration time, and transition risk required to switch after launch","The number of providers procurement plans to evaluate this quarter"],
  correct:[2],
  explanation:"Reversal cost measures what it would take to undo or migrate away from a choice after the system depends on it. Current operating cost, performance probability, and procurement scope answer different questions." },
{ id:"d6-39", domain:6, type:"single", select:1, difficulty:"hard", source:"generated",
  question:"A regulated deployment has metric alerts, but a required quarterly compliance review never occurs. What is the most likely governance defect?",
  options:["Alert thresholds were not lowered enough to make the quarterly review metric-triggered","The compliance review was linked to release activity, not the calendar, by design","The monitoring owner did not decide whether the quarter contained enough incidents","The governance table omitted a calendar trigger, an owner, and an evidence action"],
  correct:[3],
  explanation:"Some governance obligations are scheduled rather than threshold-triggered. The operating design must explicitly name the calendar trigger, owner, required action, and evidence record." },
{ id:"d6-40", domain:6, type:"single", select:1, difficulty:"core", source:"generated",
  question:"Before handoff sign-off, which test best demonstrates that the documentation is usable?",
  options:["A new operator diagnoses a staged incident and identifies the escalation boundary without help from the author","The sponsor confirms that the document links open and the architecture diagrams are current","The architect presents a final walkthrough while the operations team observes","The engineering team verifies that configuration values appear in the technical appendix"],
  correct:[0],
  explanation:"Documentation is usable when a competent recipient can act safely without relying on the author. A hands-on exercise tests both operating guidance and escalation boundaries; document inspection or presentation alone does not." },
{ id:"d6-41", domain:6, type:"single", select:1, difficulty:"core", source:"generated",
  question:"A deployment uses Amazon Bedrock for regulated work and the direct API for other tasks. Which artifact makes task ownership explicit and provides a baseline for detecting route drift?",
  options:["A network diagram showing endpoints, subnets, and firewall boundaries","A latency dashboard comparing the performance of both routes","A responsibility map naming tasks, rationale, owners, and exception approval","A procurement record containing both provider contracts and renewal dates, the authoritative source for route ownership"],
  correct:[2],
  explanation:"The responsibility map records intended task ownership and the reason for each boundary, giving reviewers a baseline for detecting and correcting drift. Runtime enforcement still requires routing controls, tests, monitoring, and an owner for exceptions." },
{ id:"d6-42", domain:6, type:"single", select:1, difficulty:"core", source:"generated",
  question:"Where should numeric SLA thresholds for an AI assistant come from?",
  options:["Match the previous vendor's targets so contract comparisons remain simple","Derive them from user expectations, business criticality, and evaluation acceptance criteria","Use the platform provider's availability figure as the user-facing service target","Choose the percentile the current architecture can meet with the least remediation work"],
  correct:[1],
  explanation:"Thresholds should trace to what users and the business require and to evidence from the agreed evaluation process. Vendor history, provider availability, or current convenience may inform design but do not define the workload's service commitment." },
{ id:"d6-43", domain:6, type:"single", select:1, difficulty:"hard", source:"generated",
  question:"Four weeks after launch, a CFO wants to approve expansion. A baseline exists, but the post-deployment outcome needs more runtime. What is the best decision?",
  options:["Approve a limited expansion, the baseline establishing opportunity, value measured after scaling","Pause expansion until a full annual trend is available for the outcome metric","Use adoption volume as the interim value metric, the control logs being complete","Hold the gate, assign the measurement owner, confirm control logging, schedule outcome measurement"],
  correct:[3],
  explanation:"The expansion decision lacks the post-deployment evidence needed to show value. The team should preserve the gate, ensure the measurement process and control evidence are operating, and schedule the decision when the outcome can be evaluated." }
]);


